%[text] # BEV Controller - Simulation Case
model_name = "HarnessModel_BEVController";
load_system(model_name) 

BEVController_Basic_params

loadLUTData_BEVController_Simple

sim_in = Simulink.SimulationInput(model_name);

sim_in = setBlockParameter(sim_in, model_name + "/BEV Speed Tracking Controller", ...
  ReferencedSubsystem = "BEVController_Basic_refsub");

sim_in = setModelParameter(sim_in, StopTime = "600");

applyToModel(sim_in)
sim_out = sim(sim_in);
%%
result = extractTimetable(sim_out.logsout);
var_names = string(result.Properties.VariableNames)';
var_units = string(result.Properties.VariableUnits)';
%[text] 
target_signal = "Vehicle speed input kph";
fig = figure; %[output:4e27f9d5]
fig.Position(3:4) = [700 300];  % width height %[output:4e27f9d5]
plot(result, "Time", target_signal, LineWidth=2) %[output:4e27f9d5]
hold on;  grid on;  axis padded %[output:4e27f9d5]
title(target_signal) %[output:4e27f9d5]
ylabel(var_units( var_names==target_signal )) %[output:4e27f9d5]
target_signal = "Motor torque command";
fig = figure; %[output:6d1faa20]
fig.Position(3:4) = [700 300];  % width height %[output:6d1faa20]
plot(result, "Time", target_signal, LineWidth=2) %[output:6d1faa20]
hold on;  grid on;  axis padded %[output:6d1faa20]
title(target_signal) %[output:6d1faa20]
ylabel(var_units( var_names==target_signal )) %[output:6d1faa20]
